-- Comentarios da Lei 15.040/2024, lote 4 (arts. 61 a 80). Autorizados pela Jessica em 22/10/2026; so a partir do texto no banco.
-- Reverter: update legislacao set contexto=null, aplicacao_pratica=null where codigo='lei15040' and numero between 61 and 80 and paragrafo is null and inciso is null;
update legislacao l set contexto=v.c, aplicacao_pratica=v.a from (values
(61,'Responsabilidade da resseguradora perante o segurado','A resseguradora, salvo disposição em contrário, e sem prejuízo do previsto no § 2º do art. 62, não responde, com fundamento no negócio de resseguro, perante o segurado, o beneficiário do seguro ou o terceiro prejudicado. O parágrafo único dispõe que é válido o pagamento feito diretamente pela resseguradora ao segurado, quando a seguradora se encontrar insolvente.'),
(62,'Notificação da resseguradora e vedação de oposição ao segurado','Demandada para revisão ou cumprimento do contrato de seguro que motivou a contratação de resseguro facultativo, a seguradora, no prazo da resposta, deverá promover a notificação judicial ou extrajudicial da resseguradora, comunicando-lhe o ajuizamento da ação, salvo disposição contratual em contrário. O § 1º dispõe que a resseguradora poderá intervir na causa como assistente simples. O § 2º dispõe que a seguradora não poderá opor ao segurado, ao beneficiário ou ao terceiro o descumprimento de obrigações por parte de sua resseguradora.'),
(63,'Destinação das prestações de resseguro adiantadas','As prestações de resseguro adiantadas à seguradora a fim de provê-la financeiramente para o cumprimento do contrato de seguro deverão ser imediatamente utilizadas para o adiantamento ou o pagamento da indenização ou do capital ao segurado, ao beneficiário ou ao terceiro prejudicado.'),
(64,'Abrangência do resseguro','Salvo disposição em contrário, o resseguro abrangerá a totalidade do interesse ressegurado, incluído o interesse da seguradora relacionado à recuperação dos efeitos da mora no cumprimento dos contratos de seguro, bem como as despesas de salvamento e as efetuadas em virtude da regulação e liquidação dos sinistros.'),
(65,'Preferência dos créditos sobre valores devidos pela resseguradora','Sem prejuízo do disposto no parágrafo único do art. 14 da Lei Complementar n. 126, de 15 de janeiro de 2007, os créditos do segurado, do beneficiário e do terceiro prejudicado têm preferência absoluta perante quaisquer outros créditos em relação aos montantes devidos pela resseguradora à seguradora, caso esta se encontre sob direção fiscal, intervenção ou liquidação.'),
(66,'Deveres do segurado ao tomar ciência do sinistro','Ao tomar ciência do sinistro ou da iminência de seu acontecimento, com o objetivo de evitar prejuízos à seguradora, o segurado é obrigado a tomar as providências necessárias e úteis para evitar ou minorar seus efeitos (inciso I); avisar prontamente a seguradora, por qualquer meio idôneo, e seguir suas instruções para a contenção ou o salvamento (inciso II); e prestar todas as informações de que disponha sobre o sinistro, suas causas e consequências, sempre que questionado a respeito pela seguradora (inciso III). O § 1º dispõe que o descumprimento doloso implica a perda do direito à indenização ou ao capital pactuado, sem prejuízo da dívida de prêmio e da obrigação de ressarcir as despesas efetuadas pela seguradora. O § 2º dispõe que o descumprimento culposo implica a perda do direito à indenização do valor equivalente aos danos decorrentes da omissão. O § 3º dispõe que os §§ 1º e 2º não se aplicam, quanto aos deveres dos incisos II e III, quando o interessado provar que a seguradora tomou ciência oportunamente do sinistro e das informações por outros meios. O § 4º dispõe que incumbe também ao beneficiário, no que couber, o cumprimento do artigo, sujeitando-se às mesmas sanções. O § 5º dispõe que as providências do inciso I não serão exigíveis se colocarem em perigo interesses relevantes do segurado, do beneficiário ou de terceiros, ou se implicarem sacrifício acima do razoável.'),
(67,'Despesas de contenção e de salvamento','As despesas com as medidas de contenção ou de salvamento para evitar o sinistro iminente ou atenuar seus efeitos, mesmo que realizadas por terceiros, correm por conta da seguradora, até o limite pactuado pelas partes, sem reduzir a garantia do seguro. O § 1º dispõe que a obrigação subsistirá ainda que os prejuízos não superem o valor da franquia contratada ou que as medidas tenham sido ineficazes. O § 2º dispõe que não constituem despesas de salvamento as realizadas com prevenção ordinária, incluída qualquer espécie de manutenção. O § 3º dispõe que a seguradora não estará obrigada ao pagamento de despesas com medidas notoriamente inadequadas, observada a garantia contratada para o tipo de sinistro iminente ou verificado. O § 4º dispõe que, se não for pactuado limite diverso, o reembolso será limitado ao equivalente a 20% (vinte por cento) do limite máximo de indenização ou capital garantido aplicável ao tipo de sinistro iminente ou verificado. O § 5º dispõe que a seguradora suportará a totalidade das despesas efetuadas com a adoção de medidas que expressamente recomendar para o caso específico, ainda que excedam o limite pactuado.'),
(68,'Preservação do local e dos elementos do sinistro','É vedado ao segurado e ao beneficiário promover modificações no local do sinistro, bem como destruir ou alterar elementos relacionados ao sinistro. O § 1º dispõe que o descumprimento culposo implica obrigação de suportar as despesas acrescidas para a regulação e a liquidação do sinistro. O § 2º dispõe que o descumprimento doloso exonera a seguradora do dever de indenizar ou pagar o capital segurado.'),
(69,'Provocação dolosa do sinistro e fraude na reclamação','A provocação dolosa de sinistro determina a perda do direito à indenização ou ao capital segurado, sem prejuízo da dívida de prêmio e da obrigação de ressarcir as despesas incorridas pela seguradora. O § 1º dispõe que a conduta prevista no inciso I do parágrafo único do art. 10 implica, além da perda do direito à indenização ou ao capital segurado, a perda da garantia, sem prejuízo da dívida de prêmio e da obrigação de ressarcir as despesas incorridas pela seguradora. O § 2º dispõe que sucede a mesma consequência do caput quando o segurado ou o beneficiário tiver prévia ciência da prática delituosa e não tentar evitá-la. O § 3º dispõe que, nos seguros sobre a vida e a integridade física, o capital segurado, ou a reserva matemática devida, será pago ao segurado ou a seus herdeiros quando o sinistro for dolosamente provocado pelo beneficiário. O § 4º dispõe que a fraude cometida por ocasião da reclamação de sinistro leva à perda pelo infrator do direito à garantia, liberando a seguradora do dever de prestar o capital segurado ou a indenização.'),
(70,'Efeitos do sinistro que se prolongam após o término do contrato','A seguradora responde pelos efeitos do sinistro caracterizado na vigência do contrato, ainda que se manifestem ou perdurem após o seu término.'),
(71,'Efeitos manifestados na vigência decorrentes de sinistro anterior','Salvo disposição em contrário, a seguradora não responde pelos efeitos manifestados durante a vigência do contrato quando decorrentes de sinistro anterior.'),
(72,'Sinistros com efeitos parciais','Salvo disposição em contrário, a ocorrência de sinistros com efeitos parciais não importa em redução do valor da garantia.'),
(73,'Defesas e exceções oponíveis ao segurado e ao beneficiário','A seguradora poderá opor ao segurado e ao beneficiário todas as defesas e exceções fundadas no contrato e anteriores ao sinistro e, salvo o caso dos seguros em que o risco coberto seja a vida ou a integridade física, também as posteriores ao sinistro.'),
(74,'Ônus da prova da lesão ao interesse garantido','Apresentados pelo interessado elementos que indiquem a existência de lesão ao interesse garantido, cabe à seguradora provar que a lesão não existiu ou que não foi, no todo ou em parte, consequência dos riscos predeterminados no contrato.'),
(75,'Regulação e liquidação do sinistro','A reclamação de pagamento por sinistro, feita pelo segurado, pelo beneficiário ou pelo terceiro prejudicado, determinará a prestação dos serviços de regulação e liquidação, que têm por objetivo identificar as causas e os efeitos do fato comunicado pelo interessado e quantificar em dinheiro os valores devidos pela seguradora, salvo quando convencionada reposição em espécie.'),
(76,'Competência exclusiva da seguradora para regular e liquidar','Cabem exclusivamente à seguradora a regulação e a liquidação do sinistro. O parágrafo único dispõe que a seguradora poderá contratar regulador e liquidante de sinistro para desenvolverem a prestação dos serviços em seu lugar, sempre reservando para si a decisão sobre a cobertura do fato comunicado pelo interessado e o valor devido ao segurado.'),
(77,'Simultaneidade da regulação e da liquidação e adiantamentos','A regulação e a liquidação do sinistro devem ser realizadas simultaneamente, sempre que possível. O parágrafo único dispõe que, apurando a existência de sinistro e de quantias parciais a pagar, a seguradora deverá adequar suas provisões e efetuar, em favor do segurado ou do beneficiário, no prazo máximo de 30 (trinta) dias, adiantamentos por conta do pagamento final.'),
(78,'Informação das quantias apuradas e responsabilidade solidária','O regulador e o liquidante do sinistro devem prontamente informar à seguradora as quantias apuradas a fim de que possam ser efetuados os pagamentos devidos ao segurado ou ao beneficiário. O parágrafo único dispõe que o descumprimento dessa obrigação acarretará a responsabilidade solidária do regulador e do liquidante pelos danos decorrentes da demora.'),
(79,'Atuação por conta da seguradora e remuneração dos auxiliares','O regulador e o liquidante de sinistro atuam por conta da seguradora. O parágrafo único veda a fixação da remuneração do regulador, do liquidante, dos peritos, dos inspetores e dos demais auxiliares com base na economia proporcionada à seguradora.'),
(80,'Deveres do regulador e do liquidante','Cumpre ao regulador e ao liquidante de sinistro exercer suas atividades com probidade e celeridade (inciso I); informar os interessados de todo o conteúdo de suas apurações, quando solicitado, respeitada a exceção prevista no parágrafo único do art. 83 (inciso II); e empregar peritos especializados, sempre que necessário (inciso III).')
) as v(n,c,a)
where l.codigo='lei15040' and l.numero=v.n and l.paragrafo is null and l.inciso is null and l.vigente;
